HDGData.TrainerEntries = {}

function HDGData:GetCatalogEntries()
    local entries = {}
    for _, item in ipairs(self.CatalogEntries or {}) do
        entries[#entries + 1] = {
            key = tostring(item.itemID or 0),
            title = item.name or ("Item " .. tostring(item.itemID or 0)),
            subtitle = string.format("%s • %s", tostring(item.expansion or "Unknown"), tostring(item.sourceLabel or "Unknown")),
            detail = string.format("HousingDecorGuide donor catalog entry. Zone: %s. DecorID: %s.", tostring(item.zone or "Unknown"), tostring(item.decorID or 0)),
            itemID = item.itemID, decorID = item.decorID, total = 1, owned = 0, entryType = "catalog", decorIds = { item.decorID or item.itemID or 0 },
        }
    end
    return entries
end

function HDGData:GetStyleEntries()
    local entries = {}
    for _, item in ipairs(self.StyleEntries or {}) do
        entries[#entries + 1] = {
            key = tostring(item.key or item.name or "style"),
            title = item.name or "Unknown Style",
            subtitle = "HousingDecorGuide style donor",
            detail = item.description or "No description.",
            total = 1, owned = 0, entryType = "style", decorIds = { 0 },
        }
    end
    return entries
end

function HDGData:GetTrainerEntries()
    local entries = {}
    for _, item in ipairs(self.TrainerEntries or {}) do
        entries[#entries + 1] = {
            key = string.format("%s:%s:%s", tostring(item.profession), tostring(item.expansion), tostring(item.faction)),
            title = item.name or "Unknown Trainer",
            subtitle = string.format("%s • %s • %s", tostring(item.profession or "Unknown"), tostring(item.expansion or "Unknown"), tostring(item.faction or "Neutral")),
            detail = string.format("HousingDecorGuide trainer donor. Location: %s. NPC: %s.", tostring(item.location or "Unknown"), tostring(item.npcID or 0)),
            npcID = item.npcID, total = 1, owned = 0, entryType = "trainer", decorIds = { item.npcID or 0 },
        }
    end
    return entries
end